<?php
declare(strict_types=1);
require_once dirname(__DIR__,2) . '/includes/app/bootstrap.php';
require_permission('users.view');
$id=query_int('id');$account=data_find('users',$id);
if($account && !data_user_within_scope($account)){http_response_code(403);render_access_denied('users.view.company_scope');exit;}
if(!$account){http_response_code(404);render_app_start('User Not Found','admin-users','Administration','The requested user record does not exist.','');render_empty_state('User not found','Return to the user directory and select another account.');render_app_end();exit;}
$activity=array_values(array_filter(data_visible_collection('audit_events'),fn($e)=>(int)($e['user_id']??0)===$id));$sessions=array_values(array_filter(data_collection('sessions'),fn($s)=>(int)$s['user_id']===$id));
render_app_start($account['name'],'admin-users','User account','View identity, memberships, roles, security requirements, activity, and sessions.','<a class="button secondary" href="'.h(app_url('admin/users.php')).'">Back to Users</a>');
?>
<div class="profile-layout admin-user-layout"><section class="profile-card"><div class="profile-avatar"><?= h(initials($account['name'])) ?></div><span class="eyebrow">User #<?= (int)$account['id'] ?></span><h2><?= h($account['name']) ?></h2><p><?= h($account['job_title']) ?> · <?= h($account['department']) ?></p><dl><div><dt>Email</dt><dd><?= h($account['email']) ?></dd></div><div><dt>Phone</dt><dd><?= h($account['phone']?:'—') ?></dd></div><div><dt>Status</dt><dd><?= badge($account['status']) ?></dd></div><div><dt>Last login</dt><dd><?= h(date_us($account['last_login'],true)) ?></dd></div><div><dt>Created</dt><dd><?= h(date_us($account['created_at'],true)) ?></dd></div><div><dt>Updated</dt><dd><?= h(date_us($account['updated_at'],true)) ?></dd></div></dl><?php if(can('users.administer')): ?><div class="control-list"><form action="<?= h(app_url('action.php')) ?>" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="require_password_reset"><input type="hidden" name="id" value="<?= $id ?>"><input type="hidden" name="return_to" value="admin/user.php?id=<?= $id ?>"><button class="button secondary full" type="submit">Require password reset</button></form><form action="<?= h(app_url('action.php')) ?>" method="post" data-confirm="Revoke every other active session for this user?"><?= csrf_field() ?><input type="hidden" name="action" value="revoke_user_sessions"><input type="hidden" name="id" value="<?= $id ?>"><input type="hidden" name="return_to" value="admin/user.php?id=<?= $id ?>"><button class="button secondary full" type="submit">Revoke user sessions</button></form><?php if($id!==(int)current_user()['id']): ?><form action="<?= h(app_url('action.php')) ?>" method="post" data-confirm="Change this account status?"><?= csrf_field() ?><input type="hidden" name="action" value="user_status"><input type="hidden" name="id" value="<?= $id ?>"><input type="hidden" name="status" value="<?= $account['status']==='active'?'suspended':'active' ?>"><input type="hidden" name="return_to" value="admin/user.php?id=<?= $id ?>"><button class="button <?= $account['status']==='active'?'danger':'primary' ?> full" type="submit"><?= $account['status']==='active'?'Suspend user':'Restore user' ?></button></form><?php endif; ?></div><?php endif; ?></section><section class="panel"><header class="panel-head"><div><span class="eyebrow">Edit identity and access</span><h2>User configuration</h2></div></header><?php if(can('users.edit')): ?><form class="form-grid settings-form" action="<?= h(app_url('action.php')) ?>" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="save_user"><input type="hidden" name="id" value="<?= $id ?>"><input type="hidden" name="return_to" value="admin/user.php?id=<?= $id ?>"><label><span>First name</span><input name="first_name" value="<?= h($account['first_name']) ?>" required></label><label><span>Last name</span><input name="last_name" value="<?= h($account['last_name']) ?>" required></label><label><span>Email</span><input type="email" name="email" value="<?= h($account['email']) ?>" required></label><label><span>Phone</span><input name="phone" value="<?= h($account['phone']) ?>"></label><label><span>Job title</span><input name="job_title" value="<?= h($account['job_title']) ?>"></label><label><span>Department</span><input name="department" value="<?= h($account['department']) ?>"></label><label><span>Status</span><select name="status"><?php foreach(['active','suspended','archived'] as $value): ?><option value="<?= h($value) ?>" <?= $account['status']===$value?'selected':'' ?>><?= h(status_label($value)) ?></option><?php endforeach; ?></select></label><label><span>Primary company</span><select name="primary_company_id"><?= company_options($account['primary_company_id']) ?></select></label><div class="span-2"><span class="field-label">Company memberships</span><?= company_checkbox_grid($account['company_ids']) ?></div><div class="span-2"><span class="field-label">Roles</span><?= role_checkbox_grid($account['role_codes']) ?></div><label class="span-2"><span>Administrative notes</span><textarea name="admin_notes" rows="4"><?= h($account['admin_notes']) ?></textarea></label><label class="span-2 toggle-row"><span><strong>Require password reset</strong><small>Force a reset at the next production sign-in.</small></span><input type="checkbox" name="require_password_reset" <?= $account['require_password_reset']?'checked':'' ?>></label><div class="span-2"><button class="button primary" type="submit">Save user</button></div></form><?php else: ?><p>This role can view the account but cannot edit it.</p><?php endif; ?></section></div>
<div class="dashboard-grid"><section class="panel"><header class="panel-head"><div><span class="eyebrow">Recent activity</span><h2>Audit events</h2></div><span class="panel-meta"><?= count($activity) ?></span></header><div class="activity-list"><?php foreach(array_slice($activity,0,8) as $event): ?><article><span><?= h(initials($account['name'])) ?></span><div><strong><?= h(status_label($event['action'])) ?></strong><small><?= h($event['module']) ?> · <?= h(status_label($event['entity_type'])) ?> #<?= h($event['entity_id']??'—') ?></small></div><time><?= h(date_us($event['created_at'],true)) ?></time></article><?php endforeach; ?></div></section><section class="panel"><header class="panel-head"><div><span class="eyebrow">Session control</span><h2>Recent sessions</h2></div><span class="panel-meta"><?= count($sessions) ?></span></header><div class="compact-list"><?php foreach($sessions as $session): ?><article><div><strong><?= h($session['device']) ?></strong><small><?= h($session['ip_address']) ?> · Last <?= h(date_us($session['last_activity'],true)) ?></small></div><?= badge($session['status']) ?></article><?php endforeach; ?></div></section></div>
<?php render_app_end(); ?>
